rules.suggestion:
优先使用智能指针替代裸指针：
```cpp
// 错误
int* ptr = new int(42);
if (condition) return; // 提前返回，ptr泄漏
delete ptr;

// 正确
auto ptr = std::make_unique<int>(42);
auto ptr2 = std::make_shared<int>(42);
```

C++代码中使用new/delete或智能指针：
```cpp
// 错误
MyClass* obj = (MyClass*)malloc(sizeof(MyClass));
obj->init(); // 构造函数未执行
free(obj);   // 析构函数不会调用

// 正确
auto obj = std::make_unique<MyClass>();
// 或
MyClass* obj = new MyClass();
delete obj;
```

使用std::unique_ptr或std::shared_ptr：
```cpp
// 不推荐
Widget* w = new Widget();
// ... 可能异常或提前返回
delete w;

// 推荐 - unique_ptr（独占所有权）
auto w = std::make_unique<Widget>();

// 推荐 - shared_ptr（共享所有权）
auto w = std::make_shared<Widget>();
```

使用安全替代函数或C++字符串类：
```cpp
// 危险
char buf[64];
strcpy(buf, user_input);
sprintf(buf, "Hello %s", name);

// 安全方式1 - 带长度限制
strncpy(buf, user_input, sizeof(buf) - 1);
buf[sizeof(buf) - 1] = '\0';
snprintf(buf, sizeof(buf), "Hello %s", name);

// 安全方式2 - 使用std::string
std::string result = std::string("Hello ") + name;
```

使用安全整数运算或在运算前检查溢出：
```cpp
// 危险
int a = INT_MAX;
int b = a + 1; // 未定义行为

// 正确方式1 - 使用无符号整数
unsigned int a = UINT_MAX;
unsigned int b = a + 1; // 安全，结果为0

// 正确方式2 - 溢出检查
if (a > INT_MAX - increment) {
    throw std::overflow_error("integer overflow");
}
int result = a + increment;

// 正确方式3 - 扩大类型
long long safe_result = (long long)a + increment;
```

使用互斥锁或原子操作保护共享数据：
```cpp
// 错误
class Counter {
    int count_ = 0;
public:
    void increment() { count_++; } // 多线程不安全
};

// 正确方式1 - 互斥锁
class Counter {
    int count_ = 0;
    mutable std::mutex mtx_;
public:
    void increment() {
        std::lock_guard<std::mutex> lock(mtx_);
        count_++;
    }
};

// 正确方式2 - 原子操作
std::atomic<int> count_{0};
count_.fetch_add(1);
```

析构函数不应抛出异常，捕获并处理所有异常：
```cpp
// 错误
class Resource {
public:
    ~Resource() {
        if (close() != 0)
            throw std::runtime_error("close failed"); // 致命
    }
};

// 正确 - 标记noexcept
class Resource {
public:
    ~Resource() noexcept {
        try {
            if (close() != 0) {
                std::cerr << "close failed" << std::endl;
            }
        } catch (...) {
            // 绝不在析构中传播
        }
    }
};
```

在容器修改后重新获取有效迭代器：
```cpp
// 错误
auto it = vec.begin();
vec.push_back(42); // it可能失效
*it = 10; // UB

// 正确方式1 - 重新获取
size_t idx = std::distance(vec.begin(), it);
vec.push_back(42);
it = vec.begin() + idx;

// 正确方式2 - erase返回下一个有效迭代器
for (auto it = vec.begin(); it != vec.end(); ) {
    if (should_remove(*it)) {
        it = vec.erase(it);
    } else {
        ++it;
    }
}
```

定义完整的特殊成员函数或使用=delete禁止拷贝：
```cpp
// 错误 - 浅拷贝导致double free
class Buffer {
    char* data_;
public:
    Buffer(size_t n) : data_(new char[n]) {}
    ~Buffer() { delete[] data_; }
    // 缺少拷贝构造和拷贝赋值
};

// 正确 - Rule of Five
class Buffer {
    char* data_;
public:
    Buffer(size_t n) : data_(new char[n]) {}
    ~Buffer() { delete[] data_; }
    Buffer(const Buffer& other); // 深拷贝
    Buffer& operator=(const Buffer& other);
    Buffer(Buffer&& other) noexcept;
    Buffer& operator=(Buffer&& other) noexcept;
};
// 或直接禁止拷贝
Buffer(const Buffer&) = delete;
Buffer& operator=(const Buffer&) = delete;
```
